const repo = "acme/web";
const candidates: { number: number; login: string }[] = [];
let page: number | null = 1;
let guard = 0;

while (page !== null && guard < 100) {
  guard++;
  const res = await tools.list_issues({ repo, state: "open", label: "perf", page });
  for (const issue of res.items) {
    const hasPerf = issue.labels.some((l) => l.name === "perf");
    if (issue.state === "open" && hasPerf && issue.assignee && issue.assignee.login) {
      candidates.push({ number: issue.number, login: issue.assignee.login });
    }
  }
  page = res.next_page;
}

const seen = new Set<number>();
const unique = candidates.filter((c) => {
  if (seen.has(c.number)) return false;
  seen.add(c.number);
  return true;
});

const results: { number: number; login: string; ok: boolean; error?: string }[] = [];
for (const c of unique) {
  try {
    await tools.post_comment({ repo, number: c.number, body: `ping @${c.login}` });
    results.push({ number: c.number, login: c.login, ok: true });
  } catch (e) {
    results.push({ number: c.number, login: c.login, ok: false, error: String((e as Error).message) });
  }
}

console.log(JSON.stringify({ found: unique.length, results }, null, 2));
return results;
```

